import { HIDE_ISO_14067_UI } from './uiVisibility';

export const REPORTING_TAB_LABELS = HIDE_ISO_14067_UI
  ? (['Overview', 'BRSR', 'ISO 14064', 'CBAM'] as const)
  : (['Overview', 'BRSR', 'ISO 14064', 'ISO 14067', 'CBAM'] as const);

export type ReportingTabLabel = (typeof REPORTING_TAB_LABELS)[number];

export const REPORTING_TAB = {
  OVERVIEW: 0,
  BRSR: 1,
  ISO_14064: 2,
  ISO_14067: HIDE_ISO_14067_UI ? -1 : 3,
  CBAM: HIDE_ISO_14067_UI ? 3 : 4,
} as const;

export const REPORTING_TAB_COUNT = REPORTING_TAB_LABELS.length;

export const REPORTING_TAB_SLUGS = {
  overview: REPORTING_TAB.OVERVIEW,
  brsr: REPORTING_TAB.BRSR,
  iso14064: REPORTING_TAB.ISO_14064,
  iso14067: REPORTING_TAB.ISO_14067,
  cbam: REPORTING_TAB.CBAM,
} as const;

export type ReportingTabSlug = keyof typeof REPORTING_TAB_SLUGS;

/** Clamps URL ?tab= values so deep links never land on an empty panel. */
export function clampReportingTab(tab: number): number {
  if (!Number.isFinite(tab) || tab < 0) {
    return 0;
  }
  if (tab >= REPORTING_TAB_COUNT) {
    return REPORTING_TAB_COUNT - 1;
  }
  if (HIDE_ISO_14067_UI && tab === 3 && REPORTING_TAB.CBAM === 3) {
    return tab;
  }
  return Math.floor(tab);
}

/** Builds `/reporting?tab=N` paths for compliance hub and navigation deep links. */
export function reportingTabHref(slug: ReportingTabSlug): string {
  let index = REPORTING_TAB_SLUGS[slug];
  if (index < 0 && slug === 'iso14067' && HIDE_ISO_14067_UI) {
    index = REPORTING_TAB.ISO_14064;
  }
  if (index < 0 || index >= REPORTING_TAB_COUNT) {
    return '/reporting';
  }
  if (index <= 0) {
    return '/reporting';
  }
  return `/reporting?tab=${index}`;
}
